                continue
            segments.append(tempStr)
            tempStr = ""
        else:
            tempStr += buffer[i]
    maxLetters = 0
    totalWordsCount = 0
    for segment in segments:
        s = segment + "_"
        letterCount = 0
        for ch in s:
            if ch.isalpha():
